# edm_construction ----
## IO correctness ----
test_that("all EDM constructors preserve layout when rebuilding the same object", {
  #' @description All four constructors replace metadata and values, preserve row-major ordering, and clear obsolete uncertainty on reconstruction.
  clear()
  withr::defer(clear())
  embedding <- methods::new(DelayEmbedding)
  id <- embedding$get_id()
  for (configuration in list(c(2L, 2L, 3L), c(1L, 1L, 1L), c(3L, 1L, 2L))) {
    dimension <- configuration[[1L]]
    lag <- configuration[[2L]]
    horizon <- configuration[[3L]]
    series <- seq_len(12L) * 10
    uncertainty <- seq_along(series) / 100
    for (method in c(
      "construct_drop_missing_with_uncertainty",
      "construct",
      "construct_with_uncertainty",
      "construct_drop_missing"
    )) {
      if (method == "construct") {
        embedding$construct(series, dimension, lag, horizon)
      } else if (method == "construct_with_uncertainty") {
        embedding$construct_with_uncertainty(series, dimension, lag, uncertainty)
      } else if (method == "construct_drop_missing") {
        embedding$construct_drop_missing(series, dimension, lag, horizon, -999)
      } else {
        embedding$construct_drop_missing_with_uncertainty(
          series, dimension, lag, horizon, -999, uncertainty
        )
      }
      state_rows <- seq.int((dimension - 1L) * lag + 1L, length(series) - horizon)
      indices <- outer(state_rows, (seq_len(dimension) - 1L) * lag, "-")
      expect_equal(embedding$get_id(), id)
      expect_equal(embedding[["embedding_dimension"]], dimension)
      expect_equal(embedding[["time_lag"]], lag)
      expect_equal(embedding[["n_rows"]], length(state_rows))
      expect_equal(embedding[["n_cols"]], dimension)
      expect_equal(
        embedding[["embedded_values"]]$get_values(),
        series[as.numeric(t(indices))]
      )
      expect_equal(
        embedding[["target_values"]]$get_values(),
        series[state_rows + horizon]
      )
      if (grepl("uncertainty", method)) {
        expect_equal(
          embedding[["embedded_uncertainty"]]$get_values(),
          uncertainty[as.numeric(t(indices))]
        )
        expect_equal(
          embedding[["target_uncertainty"]]$get_values(),
          uncertainty[state_rows + horizon]
        )
      } else {
        expect_length(embedding[["embedded_uncertainty"]]$get_values(), 0L)
        expect_length(embedding[["target_uncertainty"]]$get_values(), 0L)
      }
    }
  }
})

## Edge handling ----
test_that("EDM missing-value constructors preserve target and uncertainty alignment", {
  #' @description Missing predictors remove rows without compressing time, missing targets remain, and an empty reconstruction clears all outputs.
  clear()
  withr::defer(clear())
  embedding <- methods::new(DelayEmbedding)
  series <- c(10, -999, 30, 40, 50, -999)
  uncertainty <- seq_along(series) / 10
  for (with_uncertainty in c(TRUE, FALSE)) {
    if (with_uncertainty) {
      embedding$construct_drop_missing_with_uncertainty(
        series, 2L, 1L, 1L, -999, uncertainty
      )
      expect_equal(
        embedding[["embedded_uncertainty"]]$get_values(), c(0.4, 0.3, 0.5, 0.4)
      )
      expect_equal(
        embedding[["target_uncertainty"]]$get_values(), c(0.5, 0.6)
      )
    } else {
      embedding$construct_drop_missing(series, 2L, 1L, 1L, -999)
      expect_length(embedding[["embedded_uncertainty"]]$get_values(), 0L)
      expect_length(embedding[["target_uncertainty"]]$get_values(), 0L)
    }
    expect_equal(embedding[["n_rows"]], 2L)
    expect_equal(
      embedding[["embedded_values"]]$get_values(), c(40, 30, 50, 40)
    )
    expect_equal(embedding[["target_values"]]$get_values(), c(50, -999))
  }
  embedding$construct_drop_missing_with_uncertainty(
    rep(-999, 6), 2L, 1L, 1L, -999, uncertainty
  )
  expect_equal(embedding[["n_rows"]], 0L)
  expect_equal(embedding[["n_cols"]], 2L)
  for (field in c(
    "embedded_values", "target_values", "embedded_uncertainty", "target_uncertainty"
  )) {
    expect_length(embedding[[field]]$get_values(), 0L)
  }
  embedding$construct(c(1, 2), 1L, 1L, 1L)
  expect_equal(embedding[["n_rows"]], 1L)
  expect_equal(embedding[["embedded_values"]]$get_values(), 1)
  expect_equal(embedding[["target_values"]]$get_values(), 2)
})

## Error handling ----
test_that("EDM construction validates before replacing existing output", {
  #' @description Construction errors preserve prior output and the uncertainty-only method retains its existing stored-horizon requirement.
  clear()
  withr::defer(clear())
  embedding <- methods::new(DelayEmbedding)
  series <- as.numeric(seq_len(8L))
  expect_error(
    embedding$construct_with_uncertainty(series, 2L, 1L, rep(0.1, 8)),
    "forecast_horizon must be greater than 0"
  )
  embedding$construct(series, 2L, 1L, 2L)
  original <- embedding[["embedded_values"]]$get_values()
  expect_error(embedding$construct(series, 0L, 1L, 2L), "embedding_dimension")
  expect_error(embedding$construct(series, 2L, 0L, 2L), "time_lag")
  expect_error(embedding$construct(series, 2L, 1L, 0L), "forecast_horizon")
  expect_error(embedding$construct(series, 8L, 1L, 2L), "too short")
  expect_error(
    embedding$construct_with_uncertainty(series, 2L, 1L, 0.1),
    "uncertainty must be the same length"
  )
  expect_error(
    embedding$construct_drop_missing_with_uncertainty(
      series, 2L, 1L, 2L, -999, 0.1
    ),
    "uncertainty must be the same length"
  )
  expect_equal(embedding[["embedded_values"]]$get_values(), original)
  expect_equal(embedding[["n_rows"]], 5L)
  embedding$construct_with_uncertainty(series, 2L, 1L, rep(0.1, 8))
  expect_equal(embedding[["target_values"]]$get_values(), series[4:8])
})
